	title 'CopyBits'****************************************************************** CopyPixels** by Art Cabral and	Steven E. Glass** Copyright (C)* Apple Computer Inc., 1986-1989* All Rights Reserved**** Revision History** 18 Nov 1986  	Art Cabral** Coding begain.  Modified PPToPort into a Macintosh* style _CopyBits.	 When the source and dest rects are not * the same, the source is expanded or compressed to fit.* This routine clips all over the place.** ?? ??? ????	Steven Glass** Many revs were not summarized here.  See individual routines* for details.** 30 Jul 88	Steven Glass** CopyPixels did not always work when the left edge was clipped.* The code that calculated the alignment values was not correct* and the code that setup up the slice routines did not account* for the case where clipped images were also aligned.** 15 May 89	Steven Glass** Re-organized the code so that the StdPixels is part of the * main segment and all the stretch code is part of the CopyBits* segment.** 7/24/89	Mensch* Fix LocalNewHandle Bug. It was loading the user ID from Minrect.top instead of* UserID. It is now working properly************************************************************************************************************************************ StdPixels is at E0/1E24******************************************************************	SEG 'CopyBits'	print push	print off	include 'all.macros'	include 'special.macros'	include '::qd:qdequates:core.globals1'	include '::qd:qdequates:core.globals2'	include '::qd:qdequates:region.equs'	include '::qd:qdequates:slice.equs'	include 'stretch.equs'	include '::qd:qdequates:qd.data.asm'	include '::sys.equs.asm'	print pop	MACRO	DirtyPort	ldx #512	; switch to qdDPage2	lda <DirtyDPFlags,x	; get the proper flags	and #PortBad	; turn off both patterns	sta <DirtyDPFlags,x	MEND		title 'Imports and Entries'***************************************************	Imports	         ***************************************************	Import BusyErr	Import JoinTrickyNewHandle***************************************************	Entries	         ***************************************************	Entry UnlockHandle	Entry DerefHandle	Entry Shrink320	Entry Stretch320	Entry Copy320	Entry NoChange	Entry LocalNewHandle	Entry JmpShrink320	Entry JmpStretch320	Entry JmpCopy320	Entry PixelToEvenByte	Entry UnlockC	Entry ToStretch	Entry AlignSrc	Entry ToMerge	Entry FillSrcBuffer	Entry LocalSliceSetup	Entry SetThisShitUp	Entry StretchBits	Entry CallSP	Entry IsDestPort	Entry WideOpen	Entry copybits	title 'CopyBits'*****************************************************************CopyBits	PROC EXPORT** This is the entry point of the pixel image routine that* does stretching and shrinking.*** Notes:** Vertbackward and Horbackward can be used after slice setup is done* Shifttemp, Shifttemp2, and Thisword may be available since we're using* the nonshifting slice routines.  Steve will check if we are short of* space.  SrcSCB and so on are available depending on how you do StdPixel* stuff.  (through SrcRect) - only used	in Setup, which we are rewriting.* XferMode has to be where it is.  DestPoint and DestRect are at PortRect* and have to be where they are.  Steve	INSISTS that DstBits be copied* into DestSCB, etc.** Watch out for 32 bit _Multiply below so we can support BIG pixel maps*** Inputs (On Stack)*   SrcBits : LocInfo      ; 0*   DstBits : LocInfo      ; 4*   SrcRect : RectPtr      ; 8*   DstRect : RectPtr      ; 12*      Mode : Integer      ; 16*   MaskRgn : RgnHandle    ; 18** The LocInfo Record Looks Like**     MasterSCB	    byte*     Reserved	    byte*     PtrToPixelMap	    long*     Width	    word*     BoundsRect	    rect** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************OrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3sMaskRgn	equ RTL2+3sMode	equ sMaskRgn+4sDstRect	equ sMode+2sSrcRect	equ sDstRect+4sDstBits	equ sSrcRect+4sSrcBits	equ sDstBits+4	jsl IncBusyFlg	phd	tcd	DirtyPort* Read the source and dest LocInfo from	user to zp.	lda sSrcBits,s	; set up SrcBits in	Temp2	sta Temp2	lda sSrcBits+2,s	sta Temp2+2	lda sDstBits,s	; set up DstBits in	Temp	sta Temp	lda sDstBits+2,s	sta Temp+2	ldy #LocSize-2	; move srclocinfo to zpLoop1	tyx	lda [Temp2],y	sta SrcSCB,x	lda [Temp],y	sta DestSCB,x	dey	dey	bpl Loop1* Read source and dest rect from memory	to zp.	lda sSrcRect,s	; set up SrcRect in	Temp2	sta Temp2	lda sSrcRect+2,s	sta Temp2+2	lda sDstRect,s	; set up DstRect in	Temp	sta Temp	lda sDstRect+2,s	sta Temp+2	ldy #6Loop3	tyx	lda [Temp2],y	; copy src	sta SrcRect,x	lda [Temp],y	; copy dst	sta DestRect,x	dey	dey	bpl Loop3* Get mode and MaskRgn putting MaskRgn in RgnHandleC	lda sMode,s	; get transfer mode	sta XFerMode	lda sMaskRgn,s	sta RgnHandleC	lda sMaskRgn+2,s	sta RgnHandleC+2	ora RgnHandleC	bne MaskNotNil	lda #WideOpen	sta RgnHandleC	lda #^WideOpen	sta RgnHandleC+2MaskNotNil		;	jsr IsDestPort	bcc DestIsNotPort	jsl SetUpPortRegions ; bring clip and vis rgns to zp	bra RegionsAreSetDestIsNotPort		;	lda #WideOpen	sta RgnHandleA	sta RgnHandleB	lda #^WideOpen	sta RgnHandleA+2	sta RgnHandleB+2RegionsAreSet		;* Call CallBits to handle bottleneck stuff.	jsl CallSP	; error comes back in a	tax	; error returns in A	ldy #22	; number of paramters	jml BusyErr	ENDP	title 'CallSP'*****************************************************************CallSP	PROC** This is the routine that calls the stdPixel routine.  * looks at the destination locinfo record.  If it is the* same as the locinfo record in the current port then we* use the grafprocs in the current port.  Otherwise we* just call standard pixels.*** Inputs:*	none** Outputs:*	none** External Refs:	import IsDestPort** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************;-------------------------------------------------;; If the destination loc info is the same as; the loc info in the current graf port, I must use; the bottle neck proc in the grafport.	jsr IsDestPort	bcc UseStandard	ldy #o_GrafProcs	lda [PortRef],y	sta Temp	iny	iny	lda [PortRef],y	sta Temp+2	ora Temp	bne NotStandardUseStandard	jml StdPixelsNotStandard	phb	; put extra byte on	stack	ldy #o_stdpixels	lda [Temp],y	; get low word	pha	; put on stack	iny	; get middle and	lda [Temp],y	; high byte	sta 2,s	; overstore middle byte on stack	rtl	; go there	ENDP	title 'IsDestPort'*****************************************************************IsDestPort	PROC** Compares the destination loc info with the loc info* of the graf port.	 if they are the same, then the carry is* set.  Different, carry is clear.*** Inputs:*	Uses current direct page** Outputs:*	carry:  Set if same*	        Clear if different** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	ldy #LocSize-2Loop	tyx	lda [PortRef],y	cmp DestSCB,x	bne No	dey	dey	bpl Loop	sec	rtsNo	clc	rts	ENDP	title 'StretchBits'*****************************************************************StretchBits	PROC** This is the routine that is called when the source and * destination rectangle are not the same.*** Inputs:*	All on direct page.** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Modification History** 03 Jan 87    SEG** After SharedMRSetup (the calculation of the minrect) we were* skipping the cursor shielding.** LocalSliceSetup did not take into account the fact that the* dest rect may be clipped.** The final destination had to be aligned to a word boundry	for* clipping to work correctly.  To do this I had to adjust the* SrcPtr based on the value of DestRect+2.** DstLeft was not initialized before it	was used.** Jun 5, 1987   Steven Glass**   Fixed bug in copy pixels where right edge of image was often the*   wrong color when image was reduced by more than 2 : 1.	Problem was*   with fix ratio calculation of horizontal error term. Both the numerator*   and denominator	were 0 based values	rather than the 1 based values*   expected.**   This routine changed where DstHSize	was used to calculate*   nibble limit.  NibbleLimit is calcuated by adding DestLeft to*   a zero based counter of number of pixels.*****************************************************************	phb	; save current dbr	phd	; save the zero page	jsl SetThisShitUp	bcc SetupOKStretchError		;	pld	plb	sec	rtlSetupOK		;;----------------------------------------------------;; Call shared routine to deref 3 regions and to; make the minrect using as orig rect the intersection; of the destrect and the bounds of rgn	handle c.;	jsl SharedMRSetup	bcc SomethingLeft	brl NothingLeftSomethingLeft		;	jsl LocalSliceSetup	; call this while minrect &;		       ; dest rect are still different	moverect MinRect,DestRect ; save the resulting minrect;		       ; in destrect	jsl ShareShieldStuff ; calc rect to use	for;		       ; shielding	jsl ShieldCursor	; do the shielding	moverect DestRect,MinRect ; restore the	minrect.	jsl SetUpScanPtrs	jsl Init3Regions	stz HowFarToShift	; let setsliceadr think we are	stz HorBackward	; going to use fast	forward	stz SrcPixelMapRef	; Not Screen To Screen; 	jsl SetSliceAdr	; routines;--------------------------------------------------------;; Finally, setup SrcRef which is the pointer to the; current source scan line used by the slice routines.;	ldx #512	lda DstBuf,x	sta SrcRef	lda DstBuf+2,x	sta SrcRef+2;--------------------------------------------------------;; Set the data bank	to the bank containing the dest pixels.	pei DestRef+1	plb	plb;--------------------------------------------------------;; Switch to zero page 3 for the bulk of	the stretching code	lda ThirdZeroPage	tcd	bra NBS1	; start in middle of loop;--------------------------------------------------------;; Get first scanline of Src into SrcBuf;NextSrc	lda SrcPtr	clc	adc cSrcWidth	sta SrcPtr	bcc NBS1	inc SrcPtr+2NBS1	jsl FillSrcBuffer;----------------------------------------------------------------;; The source buffer	really should be masked on left and right; at this time so that extraneous stuff	does not mix into; real pixels.;----------------------------------------------------------------;----------------------------------------------------------------;; Bump VError by DstVSize to decide if we need to merge multple; source lines.;NextSrc2	lda VError	; as long as result	is	clc	; positive there is	no	adc DstVSize	; need to merge	sta VError	dea	bpl SrcOkMergeIt	jsl ToMerge	; oops, mergeSrcOk		;;----------------------------------------------------------------;; Now we rotate the	source buffer so that it aligns with the; the final destination.;	jsl AlignSrc;----------------------------------------------------------------;; Source and dest are aligned, call routine that does horizontal; stretching (or shrinking).;	jsl ToStretch;--------------------------------------------------------;; We've merged and stretched as appropriate.  Now we'll; switch back to the primary zero page and let the slice; routines do all the work.NoShift	lda FirstZeroPage	tcdNxtMask		;	lda CurrentY	; check for clipping on top	cmp MinRect	bmi NotThisTime	jsl Seek3Regions	clv	lda XFerMode	bpl NotInverted	sep #$40	; set v flagNotInverted		;	jsl ToSlice;--------------------------------------------------------;; Bump the dest pointers, currentY and the error term.; See if we write out this source again.;NotThisTime		;	lda DestRef	; bump the dest ref	clc	adc DestWidth	sta DestRef	bcc NBD1	inc DestRef+2	pei DestRef+1	; adjust the data bank too	plb	plbNBD1	lda CurrentY	; bump the current y	ina	cmp MinRect+4	beq Done	sta CurrentY	ldx #512	; update the error term and	lda VError,x	; see if this src is to be written	sec	; out again.	sbc SrcVSize,x	; subtract increment	sta VError,x	; VError := VError - Denom.V	bpl NxtMask;--------------------------------------------------------;; Switch back to the third zero page before we loop	lda ThirdZeroPage	tcd	bra NextSrc;--------------------------------------------------------;; Entire StretchBits complete. We're still on the first; zero page, so use	x to get rid of our	scratch; buffer, clear the	carry, and go home.Done		;	jsl UnshieldCursor	jsl FreePortRegions	jsr UnlockCNothingLeft		;	ldx #512	lda ScratchHandle+2,x	pha	lda ScratchHandle,x	pha	_DisposeHandle	pld	; restore direct page	plb	; restore bank	clc	; we did it;	rtl	ENDP	title 'Buffer Handlers'*****************************************************************FillSrcBuffer	PROC** Routine to fill the source buffer.  It is separate routine* to make debugging	easier. *** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	ldy SrcLimitSrcCopyLoop	lda [SrcPtr],y	sta [SrcBuf],y	dey	dey	bpl SrcCopyLoop	rtl	ENDP	title 'SetThisShitUp'*****************************************************************SetThisShitUp	PROC** Does the setup necessary to run the stretch routine.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 30 July 88	Steven Glass** SrcLeft and DstLeft are now calculated early in the setup* process.  (The old way put the global vale of the left * edge of the two rects here--but this could be negative * and when it was things did not work.)** Added routine GlobalPixelToWordPixel to turn a left edge into* a value for a pixel in a word.*****************************************************************	lda SrcSCB	eor DestSCB	and #$0080	beq StretchModeOk	; error if chunkiness mismatchStretchError		;	sec	rtlStretchModeOk	tdc	ldx #512	sta FirstZeroPage,x	clc	adc #512	sta ThirdZeroPage	lda DestRect	; copy this while we're on 1st zp	sta CurrentY	lda SrcSCB	; save a copy on zp[3]	sta cSrcSCB,x	lda SrcWidth	sta cSrcWidth,x* Setup DstLeft and	SrcLeft before SetupStretch.  Used for alignment* and shifting. 	lda DestRect+2	; get left of dest and convert to global coordinates	sec	; use this to calc pixel in first word	sbc DestBounds+2	pha	; save global value	phx	; save x	ldy DestSCB	jsr GlobalPixelToWordPixel	plx	; restore x	sta DstLeft,x	pla	; get global value back	jsr PixelToEvenByte	sta DestStartByte,x	lda DestRect+6	dec a	sec	sbc DestBounds+2	jsr PixelToEvenByte	sta DestFinishByte,x	lda SrcRect+2	; get left of src	sec	sbc SrcBounds+2	pha	; save global value	phx	; save x	ldy SrcSCB	jsr GlobalPixelToWordPixel	plx	; restore x	sta SrcLeft,x	; store src word pixel	pla	; get global value back.	jsr PixelToEvenByte	sta SrcStartByte,x	lda SrcRect+6	dec a	; for qd's rep of rect 	sec	sbc SrcBounds+2	jsr PixelToEvenByte	sta SrcFinishByte,x* Shift up to 3rd zero page	lda ThirdZeroPage	; switch to the 3rd	zero page	tcd	lda SrcHSize	bmi StretchError	lda DstHSize	bmi StretchError;-----------------------------------------------------------;; Calculate howfarto shift the images.;; There are three possible ways we will need to shift.;; 1.  Not at all.  The first pixel in the source is the; same as the first pixel in the dest.;; 2.  To the right.  The first pixel in the dest is a higher ; number in a word than the source.;; 3.  To the left.  The first pixel in the dest is a lower ; number in a word than in the source;; The last case is the trickiest.  Since the alignment all; takes place in the temporary source buffer we have to ; be careful as we do number three so we do now move; the pixels of first word into the second or trash; pixels as we keep them aligned.  The variable AlignAmount; is used to tell these cases apart.  If alignamount is 0, ; we have case 1.  If it is positive, we have case 2.  If; it negative, we have case 2.;	bit cSrcSCB-1	bpl ModeIs320;-----------------------------------------------------------;; Setup alignment for 640 mode.;Mode640	lda DstLeft	; AlignAmount = DstLeft-SrcLeft	sec	sbc SrcLeft	sta AlignAmount	; this is the align amount (can be negative)	bpl @ShiftRight	; if its not negative then dest is equal or to right		; of source.	clc	; If it is negative, we do a little razzledazzle	adc #8	; and see how far we need to shift into next word@ShiftRight	asl a	; turn this how far to shift into an index into	asl a	; the shift routines.	bra GotShiftAmount;-----------------------------------------------------------;; Setup alignment for 320 mode.;ModeIs320		lda DstLeft	; AlignAmount = DstLeft-SrcLeft	sec	sbc SrcLeft	sta AlignAmount	; this is the align amount (can be negative)	bpl @ShiftRight	; if its not negative then dest is equal or to right		; of source.	clc	; If it is negative, we do a little razzledazzle	adc #4	; and see how far we need to shift into next word@ShiftRight	asl a	; turn this how far to shift into an index into	asl a	; the shift routines.	asl aGotshiftAmount	sta ShiftIndex;----------------------------------------------------------------;; Now fix DstLeft and SrcLeft so that they indicate where; to start stretching nibbles.;	lda DstLeft	bit cSrcSCB-1	bpl NibbleMode	lsr aNibbleMode	sta DstLeft	sta SrcLeft;----------------------------------------------------------------;; Now use DstHSize with DstLeft to create the last nibble; in dest buffer that will be created by shrinking or stretching;	lda DstHSize	dec a	; make this into zero based counter	bit cSrcSCB-1	bpl Nohalf	lsr aNoHalf	clc	adc DstLeft	sta NibbleLimit	lda DstHSize	cmp SrcHSize	bne NotEqual	lda >JmpCopy320	sta >ToStretch	lda >JmpCopy320+2	sta >ToStretch+2	bra FinishUpNotEqual	pha	; FixRatio result	pha	bmi Shrinking	lda >JmpStretch320	sta >ToStretch	lda >JmpStretch320+2	sta >ToStretch+2	pei SrcHSize	; push denominator (Src width)	pei DstHSize	; push numerator (Dst width)	bra FixRatioShrinking	lda >JmpShrink320	sta >ToStretch	lda >JmpShrink320+2	sta >ToStretch+2	pei DstHSize	pei SrcHSizeFixRatio	_FixRatio	pla	; this is the error	part	sta HInc	; which we save	pla	; this better be zero; Used to set HError here to something but it is always reset; in the stretch and shrink routines.FinishUp		;;--------------------------------------------------------;; Calculate the size fo the buffer we use for merging; and stretching.  Then get the buffer,	and deref it.;	lda SrcFinishByte	sec	sbc SrcStartByte	sta SrcLimit	clc	adc #12	; give us some extra slop	pha	; save intermediate	result	lda DestFinishByte	sec	sbc DestStartByte	sta DstLimit	clc	adc #12	; some more extra slop	clc	adc 1,s	; add in src buffer	length	jsr LocalNewHandle	; call this one since	sta DstBuf	; it does not assume QD's zp	stx DstBuf+2	; is switched in.	sta ScratchHandle	lda DstBuf+2	sta ScratchHandle+2	lda [DstBuf]	sta SrcBuf	ldy #2	lda [DstBuf],y	sta SrcBuf+2	pla	; retrieve src buf len	clc	; DstBuf is at end of Scratch	adc SrcBuf	sta DstBuf	lda SrcBuf+2	bcc NBPtr	inaNBPtr	sta DstBuf+2;--------------------------------------------------------;; Init error term for DDA	lda SrcVSize	lsr A	eor #$FFFF	ina	sta VError	; VError := -Denom.V/2;--------------------------------------------------------;; Shift back to primary zero page	lda FirstZeroPage	tcd;--------------------------------------------------------;; Calculate SrcPtr as SrcBase + SrcTop*SrcWidth + SrcStartByte;	pha	; two words for result	pha	lda SrcRect	; get top	sec	sbc SrcBounds	; make it global	pha	; push top	pei SrcWidth	_Multiply	ldx #512	pla	clc	adc SrcPixelMapRef	; add in the base address	sta SrcPtr,x	; save the pointer	pla	adc SrcPixelMapRef+2	sta SrcPtr+2,x	lda SrcStartByte,x	clc	adc SrcPtr,x	sta SrcPtr,x	bcc NoCarryHere	lda SrcPtr+2,x	inc a	sta SrcPtr+2,xNoCarryHere		;;--------------------------------------------------------;; Calculate DestRef	as;      DstBase + DstTop*DstWidth;; Normally in QuickDraw this calculation is simple and; performed after the DestRect is clipped to the Dest; BoundsRect.  But of course this is not the case here; (otherwise why would I mention it).;; The result is that the calculation of;;     DstTop = DestRect-DestBounds;; can result in a negative number.  And	the multiply; routine we use here does not produce a signed; long result.;; It is okay for the DstBase value calucated here and; put into DestRef to be less than DestPixelMapRef because; of the strange way the algorithmn works--not doing any; drawing until DestRef is bumped to be	equal to; DestPixelMapRef.;	pha	; it was so much fun the first time...	pha	lda DestRect	; get top	sec	sbc DestBounds	; make it global	bpl NotNeg	; make it positive for now	eor #$FFFF	inc aNotNeg	pha	; push top	pei DestWidth	_Multiply	lda DestRect	cmp DestBounds	bmi ItsLess	pla	clc	adc DestPixelMapRef	sta DestRef	pla	adc DestPixelMapRef+2	sta DestRef+2	bra AllAdjustedItsLess	lda DestPixelMapRef	sec	sbc 1,s	sta DestRef	lda DestPixelMapRef+2	sbc 3,s	sta DestRef+2	pla	plaAllAdjusted	clc	rtl;-----------------------------------------------------------;GlobalPixelToWordPixel;; Routine to turn the global address of a pixel into the; number of the pixel in a word.;; Inputs:;    a-reg   Global pixel value;    y-reg   SCB to use for mode;    x-reg   nothing;; Output:;    a-reg   Pixel value in word;    y-reg   trash;    x-reg   trash;    carry   undefined.;	pha	tya	and #$0080	beq @Mode320@Mode640	pla	and #$0007	rts@Mode320	pla	and #$0003	rts;----------------------------------------------------------;; PixelToEvenByte;; Routine to convert pixel value to even byte number.; Pixel number comes in a-register and byte number goes; out in a-reg.  X & Y are undisturbed.;; Must be called when 1st zp is active. ;; (Preserves the sign of the value in the a-reg)	Export PixelToEvenBytePixelToEvenByte		;	pha	asl a	pla	ror a	bit DestSCB-1	bpl OnlyOnce	pha	asl a	pla	ror aOnlyOnce	and #$FFFE	rts	ENDP	title 'ToMerge'*****************************************************************ToMerge	PROC** Merges scan lines (used when image is compressed vertically).*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	lda SrcPtr	; first bump SrcPtr	clc	adc cSrcWidth	sta SrcPtr	bcc StartMerging	inc SrcPtr+2StartMerging	ldy SrcLimit	; set up loop	iny	sep #$20	longa offSrcMerger	lda [SrcPtr],y	; get the lowest value so far	cmp [SrcBuf],y	; can we go lower than the best?	bcs DontMerge	; if not, keep going	sta [SrcBuf],y	; if so, save the new bestDontMerge	dey	bpl SrcMerger	rep #$20	longa on	lda VError	clc	adc DstVSize	; add destination size	sta VError	; VError := VError + Numer.V	dea	bmi ToMerge	; loop while VError	<= 0	rtl	; space keeper	ENDP	title 'ToStretch'*****************************************************************ToStretch	PROC** Jumps to the routines that do the work for horizontal * scan lines.  The first jump is patched at setup time to * point to the right routine.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:	entry JmpCopy320	entry JmpStretch320	entry JmpShrink320	entry NoChange*	longa on	; mode	longi on*****************************************************************	jmp >NoChangeJmpCopy320	jmp >Copy320JmpStretch320	jmp >Stretch320JmpShrink320	jmp >Shrink320NoChange	rtl	ENDP	title 'Copy320'*****************************************************************Copy320	PROC** Copy a row from SrcBuf to DstBuf without any modification* whatsoever.** The interesting thing to note here is	that we use DstLimit* rather than SrcLimit since after aligning the src to the* dst, we may have to copy more words.**** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	ldy DstLimitCopyLoop320	lda [SrcBuf],y	sta [DstBuf],y	dey	dey	bpl CopyLoop320	rtl	ENDP	title 'Stretch320'*****************************************************************Stretch320	PROC EXPORT** Stretch a source row to the destination row, which will be contained* within our own buffer, so don't bother with the ending pixel - just* blast it in there	as needed (allocate	some slop up above).*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 30 Jan 88     Steven Glass** Once again we change the way the error term is inited.  (We've* changed this before but without making notes in the change * histories.)  Looking at Mac QD it seems that the error term* is inited to HInc	/ 2.*****************************************************************;-----------------------------------------------------------;; To init the error	term, take the calculated ratio (HInc); div by 2 and put in HError;	lda HInc	lsr a	sta HError;-----------------------------------------------------------;; 	stz NextFlag	; remembers partial	source bytes	lda SrcLeft	; We can be starting at pixel	lsr a	; 0, 1, 2 or 3 in the first word	sta SrcCtr	; use this to init SrcCtr	bcc NotOdd;----------------------------------------------------------;; The first nibble is the low nibble rather than the high.;	tay	lda [SrcBuf],y	; get this byte	sta NextNib	; put in NextNib	inc NextFlag	; bump NextFlag	inc SrcCtr	; start at one higherNotOdd		;	lda DstLeft	; get starting point of dest	sta DestNibble	; where we start storing	sta LastNibble	; DDL nibble counter* Determine how many bits to expand on this stretch run.  Assume 16 bit mode.* Leave the result in the x register.Next2Bit	ldx #0	; zero our counter	lda HErrorH2Loop	inx	; bump x until HError spills over	clc	adc HInc	bcc H2Loop	sta HError	; save DDL term	txa	; get number of nibbles to do	clc	adc LastNibble	; add nibbles done	sta LastNibble	; new nibble limit	lsr a	; Half the nibbles plus one 	ina	; is byte limit	sta ByteLimit* Load the next nibble into LoNib and Nibs.  Assume 16 bit mode.	lda NextFlag	beq ReadNibs	stz NextFlag	lda NextNib	and #$0F	; just the lower nibble	sta LoNib	asl A	asl A	asl A	asl A	ora LoNib	sta Nibs	bra GotNibbleReadNibs	inc NextFlag	ldy SrcCtr	lda [SrcBuf],y	; pick up 2 nibbles	of information	iny	sty SrcCtr	sta NextNib	; save it in x	and #$F0	; grab the first nibble	sta HTemp	; save the high nibble	lsr A	; shift it down	lsr A	lsr A	lsr A	sta LoNib	ora HTemp	; now we have a composite byte	sta NibsGotNibble	lda DestNibble	; fetch the next nibble	lsr A	; are we on a byte boundary	tay	; point y at the correct byte	bcc ByteBoundary	; yes, ignore the partial stuff	lda [DstBuf],y	; no, OR in the new	nibble	and #$FFF0	; clear first byte,	second nibble	ora LoNib	; or in the second nibble	sta [DstBuf],y	; store the composite byte	iny	tya	; y points at next byte	cpy ByteLimit	bcs NextSrc2Bit* More to do.  We know we are on a byte	boundary now, so we	can store a full* byte at a time until we run out of room.  If we go too far, no big deal.ByteBoundary	sep #$20	; no abs. refs, we promise;	lda NibsNib2Loop	sta [DstBuf],y	; store a full byte	until we run out	iny	cpy ByteLimit	bmi Nib2Loop	rep #$20	; see, kept our promise;	lda LastNibbleNextSrc2Bit	sta DestNibble	cmp NibbleLimit	bmi Next2Bit	beq Next2Bit	rtl	ENDP	title 'Shrink320'*****************************************************************Shrink320	PROC EXPORT** Shrink a 320 mode	source row into the	destination buffer.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 30 Jan 88     Steven Glass** Once again we change the way the error term is inited.  (We've* changed this before but without making notes in the change * histories.)  Looking at Mac QD it seems that the error term* is inited to HInc	/ 2.*****************************************************************;-----------------------------------------------------------;; To init the error	term, take the calculated ratio (HInc); div by 2 and put in HError;	lda HInc	lsr a	sta HError;-----------------------------------------------------------;; 	stz NextFlag	lda SrcLeft	lsr a	sta SrcCtr	bcc NotOdd; Its odd	tay	lda [SrcBuf],y	sta NextNib	inc NextFlag	inc SrcCtrNotOdd		;	lda DstLeft	sta DestNibble	; current nibble* Determine how many src nibbles to consume on this shrink run.  Assume* 16 bit mode.  Leave the result in the	x register.NextSh320	lda #$000F	; a white nibble	sta Nibs	; Nibs is our best bet yet	ldx #0	; zero our counter	lda HErrorSh320Loop	inx	; bump x until HError spills over	clc	adc HInc	bcc Sh320Loop	sta HError	; save DDL term* Examine X nibbles, saving the lowest value found in Nibs.	lda NextFlag	beq ReadSh320AnotherSh320	stz NextFlag	lda NextNib	and #$0F	; just the lower nibble	cmp Nibs	bpl TillSh320	sta NibsTillSh320	dex	beq CommonSh320ReadSh320	inc NextFlag	ldy SrcCtr	lda [SrcBuf],y	; pick up 2 nibbles	of information	iny	sty SrcCtr	sta NextNib	; save it in x	and #$00F0	; grab the first nibble	lsr A	; shift it down	lsr A	lsr A	lsr A	cmp Nibs	bpl Okay320	sta NibsOkay320	dex	bne AnotherSh320CommonSh320	lda DestNibble	; fetch the next nibble	lsr A	; are we on a byte boundary	tay	; point y at the correct byte	bcc Sh320ByteBndry	; yes, ignore the partial stuff	lda [DstBuf],y	; no, OR in the new	nibble	and #$FFF0	; clear first byte,	second nibble	ora Nibs	; or in the second nibble	sta [DstBuf],y	; store the composite byte	bra BumpDstSh320Sh320ByteBndry	lda Nibs	asl A	; shift it into the	high nibble	asl A	asl A	asl A	sta [DstBuf],y; Use DestNibble to	see if we are done.	 (in 320 mode DestNibble is; pixel number.  In	640 mode its half the pixel number) BumpDstSh320		;	lda DestNibble	ina	sta DestNibble	cmp NibbleLimit	bmi NextSh320	beq NextSh320	rtl	ENDP	title 'AlignSrc'*****************************************************************AlignSrc	PROC** Aligns the source pixles in the source buffer so that the* first pixel of the souce that is to be used in the destination* is in the right position for the destination.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	lda AlignAmount	bne MustDoSomething	rtl	; nothing to doMustDoSomething		;	bmi ShiftBackwards; shiftforewards	ldy #0	stz LastOut	ldx ShiftIndex	; do this only onceShiftFLoop	lda [SrcBuf],y	sta HTemp	jsl vxShiftStay	ora LastOut	sta [SrcBuf],y	lda HTemp	jsl vxShiftOut	sta LastOut	iny	iny	cpy SrcLimit	bcc ShiftFLoop	beq ShiftFLoop	sta [SrcBuf],y	; put the last shift out into buf	rtlShiftBackwards		;	lda [SrcBuf]	; get first word and get its shift out	ldx ShiftIndex	; we ignore its stay	jsl vxShiftOut	sta LastOut	; put this in last out and	ldy #2	; start loop with second wordShiftBLoop	lda [SrcBuf],y	; get word	sta HTemp	; save it	jsl vxShiftStay	; get its stay and or with last out	ora LastOut	; but store result back one word	dey	dey	sta [SrcBuf],y	iny	; get index back were it was	iny	lda HTemp	; get word again	jsl vxShiftOut	; get its out and put in LastOUT	sta LastOut	iny	; bump Y	iny	cpy SrcLimit	; are we done	bcc ShiftBLoop	beq ShiftBLoop	rtl	ENDP	title 'LocalSliceSetup'*****************************************************************LocalSliceSetUp	PROC** The following variables (all used by the slice routines)* are initialized here.**      NumSrcWords	           NumDestWords                 *      SrcStartWord	           DestStartWord*      SrcFinishWord           DestFinishWord** They control where the slice routines	copy to and from as	well* as how many words	are transfered.** Important Note;;;;** NumSrcWords and NumDestWords are mis-named because they really* tell me the number of bytes, not words.** This code does not have to worry about the tricky case of	the* source and dest not having the right number of bytes in them* since the transfering I will do always has the the pixels* prealigned.** This code is called right after the minrect is calculated* but before the DestRect has been replaced by this newly calculated* minrect.  In this	way I have available to me both the original* destrect and the clipped destrect;**** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*** Change History** 30 Jul 88	Steven Glass** When the destination rectangle is clipped we have to adjust* the source word.  The adjust we did before did not take into* account the fact that the source is pre-aligned.  There* were times when we did not start in the right word (we started* one too soon).*****************************************************************; Now we decide which mode were working	in so that we set up; the mode dependent stuff.  We're on the primary zero page.	stz SrcStartWord	; start by assuming	that the left;		; side at least is not clipped	ldx #512	; set x to be offset to other direct page	bit SrcSCB-1	; now do the right thing for the	bmi Is640	; two possible modes* 320 mode	lda MinRect+2	; check to see if the left side	sec	; has been clipped	sbc DestRect+2	beq NoChange320	; no.	clc	; 30 Jul 88 SEG	adc DstLeft,x	; add in SrcLeft since everything has been pre-aligned.	lsr a	; yes--make this difference into bytes	and #$FFFE	; make it even byte	sta SrcStartWordNoChange320		;	lda MinRect+2	; take the left edge of the clipped	sec	; dest rect	sbc DestBounds+2	; make global	lsr a	; turn into bytes	and #$FFFE	; make even	sta DestStartWord	; this is first dest word to hit	lda MinRect+6	; now take num pixels in clipped	sec	; rect	sbc DestBounds+2	dec a	; subtract one for QD representation;		; of rectangles	lsr a	; half it so it refers to byte	and #$FFFE	; mask so refers to	even byte	bra RazzleDazzle* 640 modeIs640		;	lda MinRect+2	; check to see if the left side	sec	; has been clipped	sbc DestRect+2	beq NoChange640	; no.	clc	; 30 Jul 88 SEG	adc DstLeft,x	; add in SrcLeft since everything has been pre-aligned.	lsr a	; yes--make this difference into bytes	lsr a	and #$FFFE	; make it even byte	sta SrcStartWordNoChange640		;	lda MinRect+2	; take the left edge of the clipped	sec	; dest rect	sbc DestBounds+2	; make global	lsr a	; turn into bytes	lsr a	and #$FFFE	; make even	sta DestStartWord	; this is first dest word to hit	lda MinRect+6	; now take num pixels in clipped	sec	; rect	sbc DestBounds+2	dec a	; subtract one for QD representation;		; of rectangles	lsr a	; half it so it refers to byte	lsr a	and #$FFFE	; mask so refers to	even byteRazzleDazzle	sta DestFinishWord	sec	sbc DestStartWord	sta NumDestWords	sta NumSrcWords	clc	adc SrcStartWord	sta SrcFinishWord	rtl	ENDP	title 'Various Utilities'*****************************************************************LocalNewHandle	PROC** Routine to return	a new handle of size passed in a-reg** Handle is returned in a,x (a low, x high).** This is different	than MyWNewHandle in that QuickDraw's* zero page is stored in the same place	that MyWNewHandle* knows about.**** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** 7/24/89	Mensch*	Change Where the user ID comes fromwhen allocating the handle.*****************************************************************	pha	pha	pea 0	pha	ldx FirstZeroPage	lda >UserID,x	; get proper ID.	pha	pea 0	; attributes	pha	; junk for space	pha	_NewHandle	pla	plx	rts	ENDP*****************************************************************DeRefAndLock	PROC** This takes a handle in the A & X registers and dereferences* and locks it.** The result ptr is	returned in a & x.** The location TEMP	on zero page is trashed as is Y*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:	ENTRY DeRefAndLoc	; another name for this proc*	longa on	; mode	longi on*****************************************************************DeRefAndLoc	sta Temp	stx Temp+2	ldy #4	lda [Temp],y	ora #$8000	sta [Temp],y	dey	dey	lda [Temp],y	tax	lda [Temp]	rts	ENDP*****************************************************************UnlockMem	PROC** This is used after a handle has been locked to release it.** Like DeRefAndLock, the handle is passed in the A & X registers.**** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	sta Temp	stx Temp+2	ldy #4	lda [Temp],y	and #$7FFF	sta [Temp],y	rts	ENDP****************************************************************** DeRefA*****************************************************************DeRefA	PROC EXPORT	ldx #RgnHandleA	jsr DerefHandle	sta RgnPtrA	stx RgnPtrA+2	rts	ENDP****************************************************************** UnlockA*****************************************************************UnlockA	PROC EXPORT	ldx #RgnHandleA	jmp UnlockHandle	ENDP****************************************************************** DeRefB*****************************************************************DeRefB	PROC EXPORT	ldx #RgnHandleB	jsr DerefHandle	sta RgnPtrB	stx RgnPtrB+2	rts	ENDP****************************************************************** UnlockB*****************************************************************UnlockB	PROC EXPORT	ldx #RgnHandleB	jmp UnlockHandle	ENDP****************************************************************** DeRefC*****************************************************************DeRefC	PROC EXPORT	ldx #RgnHandleC	jsr DerefHandle	sta RgnPtrC	stx RgnPtrC+2	rts	ENDP****************************************************************** UnlockC*****************************************************************UnlockC	PROC EXPORT	ldx #RgnHandleC	jmp UnlockHandle	ENDP****************************************************************** DerefHandle*****************************************************************DerefHandle	PROC EXPORT* enter with zero page offset to src in	X* sample usage:**     ldx #RgnHandleA*     jsr DerefHandle*     sta RgnPtrA*     stx RgnPtrA+2	lda 0,x	sta Temp	lda 2,x	sta Temp+2	Export QuickDerefQuickDeref* sample usage:*     jsr QuickDeref	; Temp still has handle*     sta RgnPtrA*     stx RgnPtrA+2* handle is in Temp; lock it down	ldy #4	lda [Temp],y	ora #$8000	sta [Temp],y* dereference it, leaving low word in A	and high word in X	ldy #2	lda [Temp],y	tax	lda [Temp]	rts	ENDP****************************************************************** Procedure UnlockHandle*****************************************************************UnlockHandle	PROC EXPORT* enter with zero page offset to handle	in x* Sample usage**     ldx #RgnHandleA*     jsr UnlockHandle	lda 0,x	sta Temp	lda 2,x	sta Temp+2* unlock it	ldy #4	lda [Temp],y	and #$7FFF	sta [Temp],y* leave with Temp still holding the handle so related routines* can use it	rts	ENDP****************************************************************** WideOpen** This is a fake region containing a bounding box equal* to the potential drawing space.*****************************************************************WideOpen	PROC EXPORT	DC.L There	DS.B 2There	DC.W 10	DC.W -MaxInt,-MaxInt,MaxInt,MaxInt	ENDPForceCopyBitLoad	PROC EXPORT	rtl	ENDP	title 'StdPixels'	SEG 'MAINPart'*****************************************************************iStdPixels	PROC EXPORT** Standard pixel painting routine.  Inputs are already on* zero page as follows when this gets control.**        SrcLocInfo*        DestLocInfo (this lives in same memory as PortLocInfo)*        SrcRect*        DestRect*        XFerMode*        RgnHandleA*        RgnHandleB*        RgnHandleC	(MaskRgn)**** Inputs:*	All on direct page.** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** June ?, 1986	Steven Glass**  This routine did not handle source and destination pixel maps *  crossing bank boundries until now.** August 8, 1986	Steven Glass**   When the src and dest pixel maps were not equal chunkiness, *   the bank reg was left on stack and system crashed.** November 18, 1986**   It now handles stretching. oh my.** Jun 5, 1987	Steven Glass**   Fixed bug in copy pixels where right edge of image was often the*   wrong color when image was reduced by more than 2 : 1.	Problem was*   with fix ratio calculation of horizontal error term. Both the numerator*   and denominator	were 0 based values	rather than the 1 based values*   expected.**   This routine changed where SrcHSize	and DstHSize are calculated.*   Both were calculated as Right-1 - Left.  It is now Right - Left.******************************************************************	stz ClipToPortToo;-------------------------------------------------;; If the dest loc is the same as the current; graf port, then we check if a picture	is being; captured.;	jsr LocalIsDestPort	bcc SkipPicture	lda #$FFFF	sta ClipToPortToo	lda #MapNoun	jsl PutPictStuff	bcc NoPicErrQuitNow	rtlNoPicErr		;SkipPicture	ldy #o_PnVis	lda [PortRef],y	bpl KeepGoing	lda #$0000	clc	rtl* Calc DestRect Height:Width LongintKeepGoing		;	ldx #512	lda DestRect+4	sec	sbc DestRect	sta DstVSize,x	lda DestRect+6	sec	sbc DestRect+2	sta DstHSize,x* Calc SrcRect Height:Width Longint	lda SrcRect+4	sec	sbc SrcRect	sta SrcVSize,x	lda SrcRect+6	sec	sbc SrcRect+2	sta SrcHSize,x* if they are the same then can fall into RgnBlt.  If different, go* through stretch.	cmp DstHSize,x	bne NotEqual	lda SrcVSize,x	cmp DstVSize,x	bne NotEqual	jml RgnBltNotEqual		jsl ForceCopyBitLoad	jml StretchBitsLocalIsDestPort	ldy #LocSize-2Loop	tyx	lda [PortRef],y	cmp DestSCB,x	bne No	dey	dey	bpl Loop	sec	rtsNo	clc	rts	ENDP	END